      const ids = [...(c.lead ? [c.lead.personId] : []), ...c.members.map((m) => m.personId)];
      const total = ids.reduce((sum, id) => {
        const d = due.get(id);
        return d == null ? sum : sum + cents(d);
      }, 0);
      return [c.name, total];
    }),
  );
}

